# Adds the dohcUITests target (sources in apps/mobile/uitests) to the generated iOS project and its scheme.
# ios/ is regenerated by prebuild, so run this after prebuild; it does nothing when the target is already there.
# Usage: ruby scripts/add-ui-tests.rb   (from apps/mobile)
require 'xcodeproj'

root = File.expand_path('..', __dir__)
project = Xcodeproj::Project.open(File.join(root, 'ios/dohc.xcodeproj'))
app = project.targets.find { |target| target.name == 'dohc' } or abort('no dohc target')
name = 'dohcUITests'
tests = project.targets.find { |target| target.name == name }
unless tests
  tests = project.new_target(:ui_test_bundle, name, :ios, '16.4')
  tests.add_dependency(app)
end
group = project.main_group[name] || project.main_group.new_group(name, File.join(root, 'uitests'), :absolute)
Dir[File.join(root, 'uitests/*.swift')].sort.each do |path|
  next if group.files.any? { |file| file.real_path.to_s == path }
  tests.add_file_references([group.new_reference(path, :absolute)])
end
tests.build_configurations.each do |config|
  config.build_settings.merge!(
    'TEST_TARGET_NAME' => 'dohc', 'PRODUCT_NAME' => '$(TARGET_NAME)', 'PRODUCT_BUNDLE_IDENTIFIER' => 'app.dohc.mobile.uitests',
    'GENERATE_INFOPLIST_FILE' => 'YES', 'SWIFT_VERSION' => '5.0', 'IPHONEOS_DEPLOYMENT_TARGET' => '16.4',
    'TARGETED_DEVICE_FAMILY' => '1,2', 'CODE_SIGNING_ALLOWED' => 'NO',
  )
end
project.save

scheme_path = File.join(root, 'ios/dohc.xcodeproj/xcshareddata/xcschemes/dohc.xcscheme')
scheme = Xcodeproj::XCScheme.new(scheme_path)
unless scheme.test_action.testables.any? { |testable| testable.buildable_references.any? { |ref| ref.target_name == name } }
  scheme.test_action.add_testable(Xcodeproj::XCScheme::TestAction::TestableReference.new(tests))
  scheme.save!
end
puts "#{name} ready"
